css:
.quantum-wave {
  width: 100%;
  height: 100%;
  background: linear-gradient(
    135deg,
    rgba(139, 139, 139, 0.455) 0%,
    rgba(66, 66, 66, 0.836) 50%,
    rgba(0, 0, 0, 0.85) 100%
  );
  filter: url(#quantum-texture);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.quantum-wave::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.3);
  pointer-events: none;
}
